const mongoose = require('mongoose');

// A queued password-reset email.
//
// The request that asks for a reset link no longer sends the mail itself: it
// records this job and answers at once, so the response time cannot tell an
// unauthenticated caller whether an address has an account. The job is a
// document in the application's own database, so it is durable: a request that
// was accepted is still delivered after a restart or a crash.
//
// The job holds no reset token. The token is generated by the worker when the
// job is delivered, so the raw token only ever exists in memory and in the
// emailed link, and the database only ever sees its SHA-256 hash.

const JOB_STATUSES = ['pending', 'sending', 'sent', 'failed', 'skipped'];

const passwordResetEmailJobSchema = new mongoose.Schema(
  {
    // The account the link belongs to. The worker resolves it again when the
    // job runs, so an account that was removed in the meantime is skipped
    // instead of mailed.
    user: { type: mongoose.Schema.Types.ObjectId, required: true, ref: 'User' },
    // The address the request was made for, captured when the job was queued.
    to: { type: String, required: true, lowercase: true, trim: true },
    status: { type: String, enum: JOB_STATUSES, default: 'pending' },
    // When the worker took the job. A claim that is never finished is taken
    // back after a while, so a crash cannot strand a job.
    claimedAt: { type: Date, default: null },
    sentAt: { type: Date, default: null },
    failedAt: { type: Date, default: null },
    completedAt: { type: Date, default: null },
    // The sanitised description of a failed delivery. Never the raw error, so
    // no token, reset link, API key or address can be stored here.
    lastError: { type: String, default: null }
  },
  { timestamps: true }
);

// The worker claims the oldest pending job.
passwordResetEmailJobSchema.index({ status: 1, createdAt: 1 });

// Only completed jobs have this timestamp, so TTL can never remove an open job.
passwordResetEmailJobSchema.index({ completedAt: 1 }, { expireAfterSeconds: 24 * 60 * 60 });

module.exports = mongoose.model('PasswordResetEmailJob', passwordResetEmailJobSchema);
module.exports.JOB_STATUSES = JOB_STATUSES;
